//! effect 元数据的唯一声明表（issue #70）：每个操作在此登记一次真实分发效果，
//! 描述符 JSON 的 effect 字段从这里渲染，不再在各模块描述符里手写第二份。
//! 声明与公开契约冻结快照逐字对照（operation_registry::public_operation_contracts_are_frozen）。
//! sync.*/schedule.* 家族公开契约本就未声明 effect，保持缺失。

use serde_json::{json, Value};
use std::sync::OnceLock;

pub(crate) fn effect(name: &str) -> Option<&'static Value> {
    static EFFECTS: OnceLock<std::collections::BTreeMap<String, Value>> = OnceLock::new();
    EFFECTS.get_or_init(build).get(name)
}

